package edu.seu.vcampus.common.course;
import java.io.*; import java.util.*;
/** Optimistically updates an offering aggregate without accepting a client counter. */
public record UpdateOfferingCommand(String offeringId,String termId,String courseId,String teacherUserId,String className,int capacity,String offeringStatus,long expectedVersion,List<CreateOfferingCommand.ScheduleInput> schedules) implements Serializable { @Serial private static final long serialVersionUID=1L; public UpdateOfferingCommand{Objects.requireNonNull(offeringId);Objects.requireNonNull(termId);Objects.requireNonNull(courseId);Objects.requireNonNull(teacherUserId);Objects.requireNonNull(className);Objects.requireNonNull(offeringStatus);schedules=List.copyOf(schedules);if(offeringId.isBlank()||capacity<1||expectedVersion<0)throw new IllegalArgumentException("invalid offering");} }
